INSERT INTO expense_budget_review(trace_id,tenant_id,report_id,application_id,employee_id,round_no,submitted_financial_version,
    precheck_id,original_operation_id,target_digest,budget_node_id,policy_reference,version,status,input_json,state_json,
    submitted_at,updated_at,next_check_at)
SELECT #{traceId},#{tenantId},#{reportId},#{applicationId},#{employeeId},#{roundNo},#{submittedFinancialVersion},#{precheckId},#{originalOperationId},#{targetDigest},#{budgetNodeId},#{policy},1,'WAITING_BUDGET',#{stateJson},#{stateJson2},#{submittedAt},#{updatedAt},#{updatedAt2}
FROM approval_application WHERE tenant_id=#{expectedTenantId} AND id=#{id} AND status='IN_APPROVAL' AND round_no=#{expectedRoundNo}

